# Find the 4->3 cells
for r in range(h):
    for c in range(w):
        if io[r, c] == 4:
            neighbors_up = []
            neighbors_down = []
            neighbors_left = []
            neighbors_right = []
            if r > 0 and io[r-1, c] != bg:
                neighbors_up.append((r-1, c, int(io[r-1, c])))
            if r < h-1 and io[r+1, c] != bg:
                neighbors_down.append((r+1, c, int(io[r+1, c])))
            if c > 0 and io[r, c-1] != bg:
                neighbors_left.append((r, c-1, int(io[r, c-1])))
