                neighbors_right.append((r, c+1, int(io[r, c+1])))
            if io_out[r, c] == 3:
                print(f"4 at ({r},{c}) changed to 3. Neighbors: {neighbors}")

# Let me visualize the 4 regions
print("\n4 region analysis:")
coords = []
for r in range(h):
    for c in range(w):
        if io[r, c] == 4:
            coords.append((r, c))
print(f"4 cells: {coords}")

# See which 4 cells are connected
visited = set()
def bfs(start):
    component = []
    stack = [start]
    while stack:
        r, c = stack.pop()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        component.append((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and io[nr, nc] == 4 and (nr, nc) not in visited:
                stack.append((nr, nc))
    return component

visited.clear()
components = []
for r, c in coords:
    if (r, c) not in visited:
        comp = [(io[r,c], len(bfs((r,c))))]
visited2 = set()
for r, c in coords:
    comp = []
    stack = [(r,c)]
    while stack:
        cr, cc = stack.pop()
        if (cr, cc) in visited2:
            continue
        visited2.add((cr, cc))
        comp.append((cr, cc))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < h and 0 <= nc < w and io[nr, nc] == 4 and (nr, nc) not in visited2:
                stack.append((nr, nc))
    components.append((len(comp), comp))

print(f"Components: {sorted(components, reverse=True)}")
for size, cells in sorted(components, reverse=True):
    print(f"  Size {size}: {cells}")

# Check adjacency between 4 and 3 region
sub_3 = set()
for r in range(h):
    for c in range(w):
        if io[r, c] == 3:
            sub_3.add((r,c))
print(f"\n3 cells: {sub_3}")

# Check if any 4 is adjacent to 3
print("\n4 cells adjacent to 3:")
for r, c in coords:
